  "Opportunities lists events near you. Tap When I'm free to see only the ones that fit your week, and sign up for every date of a weekly event at once.": "সুযোগ অংশে আপনার কাছের ইভেন্ট দেখায়। শুধু আপনার সপ্তাহে মেলে এমনগুলো দেখতে যখন আমি ফাঁকা চাপুন, এবং সাপ্তাহিক ইভেন্টের সব তারিখে একবারে সাইন আপ করুন।",
  "Check in at events": "ইভেন্টে চেক ইন করুন",
