  "Please upload proof — a sign-in sheet, thank-you email, or other supporting document.": "প্রমাণ আপলোড করুন — হাজিরা শিট, ধন্যবাদ ইমেল, বা অন্য সহায়ক নথি।",
  "Your hours are saved, but we couldn’t make the signing link — check you’re online and signed in. Your supervisor can still sign in person.": "আপনার ঘণ্টা সংরক্ষিত হয়েছে, কিন্তু আমরা সাইনিং লিঙ্ক তৈরি করতে পারিনি — দেখুন আপনি অনলাইনে এবং সাইন ইন আছেন কি না। আপনার সুপারভাইজার এখনও সামনাসামনি স্বাক্ষর করতে পারেন।",
  "Could not save — your proof file might be too large. Try a smaller image.": "সংরক্ষণ করা যায়নি — আপনার প্রমাণ ফাইল সম্ভবত খুব বড়। ছোট ছবি দিয়ে চেষ্টা করুন।",
