  "We also text them the link. Good for supervisors who don’t check email. The number is deleted after 30 days.": "আমরা লিঙ্কটি SMS-এও পাঠাই। যারা ইমেল দেখেন না তাদের জন্য ভালো। ৩০ দিন পর নম্বরটি মুছে ফেলা হয়।",
  "{organizer} reviews and signs this on their My Tasks page in VolunTrack — no email is sent.": "{organizer} VolunTrack-এ তাঁর আমার কাজ পাতায় এটি পর্যালোচনা করে স্বাক্ষর করেন — কোনো ইমেল পাঠানো হয় না।",
  "The task organizer": "কাজের আয়োজক",
