  "Signed up. A parent needs to OK this first: ask them to make a VolunTrack parent account and link to you with the code from Settings → Family.": "সাইন আপ হয়েছে। আগে অভিভাবকের অনুমোদন দরকার: তাঁকে VolunTrack অভিভাবক অ্যাকাউন্ট খুলে সেটিংস → পরিবার-এর কোড দিয়ে আপনার সাথে যুক্ত হতে বলুন।",
