  "Your child is under 13, so these sign-ups reach the organizer only after you approve them.": "আপনার সন্তানের বয়স ১৩-এর কম, তাই এই সাইনআপগুলো আপনার অনুমোদনের পরই আয়োজকের কাছে যায়।",
  "The organizer's waiver: approving also agrees to it for your child": "আয়োজকের দায়মুক্তিপত্র: অনুমোদন করলে আপনার সন্তানের হয়ে এতেও সম্মতি দেওয়া হয়",
