  "Other language…": "অন্য ভাষা…",
  "Open VolunTrack in your phone’s web browser (Chrome or Safari) using the button below, and sign in.": "নিচের বোতাম দিয়ে আপনার ফোনের ওয়েব ব্রাউজারে (Chrome বা Safari) VolunTrack খুলুন এবং সাইন ইন করুন।",
  "Then use the browser’s translate, as shown below.": "তারপর নিচে দেখানো মতো ব্রাউজারের অনুবাদ ব্যবহার করুন।",
  "Use VolunTrack in another language": "অন্য ভাষায় VolunTrack ব্যবহার করুন",
  "VolunTrack is written in English, Spanish, Vietnamese and Chinese, and its main screens in Hindi, Arabic, Portuguese, French, Bengali, Russian and Japanese. For any other language, your browser can translate the page for you. It’s free and works for 100+ languages, like Tagalog, Korean, Haitian Creole, German and Urdu.": "VolunTrack ইংরেজি, স্প্যানিশ, ভিয়েতনামি ও চীনা ভাষায় আছে, আর এর প্রধান স্ক্রিনগুলো হিন্দি, আরবি, পর্তুগিজ, ফরাসি, বাংলা, রুশ ও জাপানি ভাষাতেও আছে। অন্য যেকোনো ভাষার জন্য আপনার ব্রাউজার পাতাটি অনুবাদ করতে পারে। এটি বিনামূল্যে এবং ১০০টিরও বেশি ভাষায় কাজ করে, যেমন তাগালগ, কোরিয়ান, হাইতিয়ান ক্রেওল, জার্মান ও উর্দু।",
  "computer": "কম্পিউটার",
  "Right-click anywhere on the page, choose Translate to…, then pick your language.": "পাতার যেকোনো জায়গায় রাইট-ক্লিক করুন, অনুবাদ করুন… বেছে নিন, তারপর আপনার ভাষা বেছে নিন।",
  "Android phone": "Android ফোন",
  "Tap ⋮ (top right), then Translate…, then pick your language.": "⋮ (উপরে ডানে) চাপুন, তারপর অনুবাদ করুন…, তারপর আপনার ভাষা বেছে নিন।",
  "iPhone": "iPhone",
  "Tap the page menu (aA or the icon at the left of the address bar), then Translate to….": "পাতার মেনু (aA বা ঠিকানা বারের বাঁদিকের আইকন) চাপুন, তারপর অনুবাদ করুন….",
  "Mac": "Mac",
  "Click the translate icon in the address bar, or choose View → Translation.": "ঠিকানা বারে অনুবাদ আইকনে ক্লিক করুন, বা দেখুন → অনুবাদ বেছে নিন।",
  "Browser translation is done by your browser, not by VolunTrack, and may not be perfect. Emails still come in English or your chosen VolunTrack language.": "ব্রাউজারের অনুবাদ আপনার ব্রাউজার করে, VolunTrack নয়, তাই এটি নিখুঁত নাও হতে পারে। ইমেল এখনও ইংরেজিতে বা আপনার বেছে নেওয়া VolunTrack ভাষায় আসে।",
  "Open in browser": "ব্রাউজারে খুলুন",
