  "You are already linked to another school. Joining asks {school} to accept your transfer, and your hours move with you.": "আপনি ইতিমধ্যে অন্য স্কুলের সাথে যুক্ত। যোগ দিলে {school}-কে আপনার বদলি গ্রহণ করতে বলা হবে, আর আপনার ঘণ্টা আপনার সাথে যাবে।",
