  "Parent or guardian's name": "বাবা-মা বা অভিভাবকের নাম",
  "Your parent sees this waiver when they OK your sign-up, and approving it agrees for you.": "আপনার সাইন আপ অনুমোদন করার সময় অভিভাবক এই সম্মতিপত্র দেখবেন, আর অনুমোদন করলেই আপনার হয়ে সম্মতি দেওয়া হবে।",
