  "They sign with a finger and tap Done. The signature shows up here by itself. The code works once, for 15 minutes.": "তিনি আঙুল দিয়ে স্বাক্ষর করে Done ট্যাপ করবেন। স্বাক্ষর নিজে থেকেই এখানে দেখাবে। কোডটি একবারই, ১৫ মিনিটের জন্য কাজ করে।",
  "Waiting for the signature…": "স্বাক্ষরের অপেক্ষায়…",
