  "{n} sessions of volunteering": "স্বেচ্ছাসেবার {n}টি সেশন",
  "Top cause": "প্রধান উদ্দেশ্য",
  "Places helped": "সাহায্য করা জায়গা",
  "Busiest month": "সবচেয়ে ব্যস্ত মাস",
