  "Could not make the image.": "ছবিটি তৈরি করা যায়নি।",
  "My volunteer hours, tracked with VolunTrack: {site}": "আমার স্বেচ্ছাসেবার ঘণ্টা, VolunTrack দিয়ে ট্র্যাক করা: {site}",
  "Share my hours": "আমার ঘণ্টা শেয়ার করুন",
  "A picture of your hours for Instagram, a story, or a college application.": "Instagram, স্টোরি বা কলেজের আবেদনের জন্য আপনার ঘণ্টার একটি ছবি।",
  "Your volunteer hours: {n} hours of service": "আপনার স্বেচ্ছাসেবার ঘণ্টা: {n} ঘণ্টা সেবা",
