  "This school year": "এই শিক্ষাবর্ষ",
  "No approved hours yet for this period. Yours could be first!": "এই সময়ে এখনও কোনো অনুমোদিত ঘণ্টা নেই। আপনারটাই প্রথম হতে পারে!",
  "Nobody is on the leaderboard yet. Join and be the first!": "লিডারবোর্ডে এখনও কেউ নেই। যোগ দিন এবং প্রথম হোন!",
  "You're #{rank} with {hours} approved hours.": "{hours} অনুমোদিত ঘণ্টা নিয়ে আপনি #{rank}।",
  "You're on the leaderboard. Classmates see your first name, last initial and approved hours.": "আপনি লিডারবোর্ডে আছেন। সহপাঠীরা আপনার নামের প্রথম অংশ, পদবির প্রথম অক্ষর আর অনুমোদিত ঘণ্টা দেখে।",
  "Join to appear here. Only students at your school see it: your first name, last initial and approved hours.": "এখানে দেখাতে যোগ দিন। শুধু আপনার স্কুলের শিক্ষার্থীরা এটি দেখে: আপনার নামের প্রথম অংশ, পদবির প্রথম অক্ষর আর অনুমোদিত ঘণ্টা।",
  "Join the leaderboard": "লিডারবোর্ডে যোগ দিন",
  "Monthly progress email": "মাসিক অগ্রগতির ইমেল",
  "On. After a month you logged hours, we'll email you on the 1st with what you logged and how close you are to your goal.": "চালু। যে মাসে ঘণ্টা লিখেছেন তার পরে, ১ তারিখে আমরা আপনাকে ইমেল করে জানাব কী লিখেছেন এবং লক্ষ্যের কতটা কাছে আছেন।",
  "Off. We won't email you a monthly summary of your hours.": "বন্ধ। আমরা আপনার ঘণ্টার মাসিক সারাংশ ইমেল করব না।",
  "{name} invited you to VolunTrack": "{name} আপনাকে VolunTrack-এ আমন্ত্রণ জানিয়েছে",
  "You're invited to VolunTrack": "আপনাকে VolunTrack-এ আমন্ত্রণ জানানো হয়েছে",
  "Track your volunteer hours free: log hours in a minute, see your goal, and download a report when it is due.": "বিনামূল্যে স্বেচ্ছাসেবার ঘণ্টা ট্র্যাক করুন: এক মিনিটে ঘণ্টা লিখুন, লক্ষ্য দেখুন, আর জমার সময় হলে রিপোর্ট ডাউনলোড করুন।",
  "Log hours in under a minute, from your phone.": "ফোন থেকে এক মিনিটের কম সময়ে ঘণ্টা লিখুন।",
  "See how close you are to your goal.": "লক্ষ্যের কতটা কাছে আছেন দেখুন।",
  "Download a report when your hours are due.": "ঘণ্টা জমার সময় হলে রিপোর্ট ডাউনলোড করুন।",
  "The free way for students to track volunteer hours.": "শিক্ষার্থীদের স্বেচ্ছাসেবার ঘণ্টা ট্র্যাক করার বিনামূল্যের উপায়।",
  "You already have an account.": "আপনার আগেই একটি অ্যাকাউন্ট আছে।",
  "I track my volunteer hours on VolunTrack. It is free. Join me:": "আমি VolunTrack-এ আমার স্বেচ্ছাসেবার ঘণ্টা ট্র্যাক করি। এটি বিনামূল্যে। আমার সাথে যোগ দাও:",
  "Earn the Bring a Friend badge when a friend joins with your link.": "আপনার লিংক দিয়ে কোনো বন্ধু যোগ দিলে বন্ধু আনুন ব্যাজ পান।",
  "{n} of 5 friends joined. Reach 5 for the Team Builder badge.": "৫ জনের মধ্যে {n} জন বন্ধু যোগ দিয়েছে। দল গড়ুন ব্যাজের জন্য ৫ জনে পৌঁছান।",
  "{n} friends joined. Thank you for spreading the word!": "{n} জন বন্ধু যোগ দিয়েছে। কথাটা ছড়ানোর জন্য ধন্যবাদ!",
  "Volunteering is better together. Send friends your link so they can track their hours too.": "একসাথে স্বেচ্ছাসেবা আরও ভালো। বন্ধুদের আপনার লিংক পাঠান যাতে তারাও তাদের ঘণ্টা ট্র্যাক করতে পারে।",
  "1 friend joined": "১ জন বন্ধু যোগ দিয়েছে",
