  "Generate a 5-digit PIN to sync your account with the mobile app. Enter it on your phone within 15 minutes — it works once.": "মোবাইল অ্যাপের সাথে অ্যাকাউন্ট সিঙ্ক করতে ৫ সংখ্যার পিন তৈরি করুন। ১৫ মিনিটের মধ্যে ফোনে দিন — এটি একবারই কাজ করে।",
