  "Family": "পরিবার",
  "Share with a parent": "অভিভাবকের সাথে শেয়ার করুন",
  "Generate a code and share it with a parent so they can follow your logged hours and verification status. Only hours logged from now on will be visible to them. Each code works once — generate another for a second parent.": "একটি কোড তৈরি করে অভিভাবকের সাথে শেয়ার করুন, যাতে তিনি আপনার লেখা ঘণ্টা আর যাচাইয়ের অবস্থা দেখতে পারেন। শুধু এখন থেকে লেখা ঘণ্টা তিনি দেখতে পাবেন। প্রতিটি কোড একবার কাজ করে — দ্বিতীয় অভিভাবকের জন্য আরেকটি তৈরি করুন।",
