  "Your logged hours are stored on this device. If you've created an account, some features above (Family sharing, school linking, cross-device sync, two-factor authentication) also store data on our server. Sign out below to clear your session.": "আপনার লেখা ঘণ্টা এই ডিভাইসে সংরক্ষিত। আপনি অ্যাকাউন্ট খুলে থাকলে, উপরের কিছু ফিচার (পরিবারের সাথে শেয়ার, স্কুল যুক্ত করা, ডিভাইসের মধ্যে সিঙ্ক, দুই-ধাপের যাচাইকরণ) আমাদের সার্ভারেও ডেটা রাখে। আপনার সেশন মুছতে নিচে সাইন আউট করুন।",
