  "Passkeys": "পাসকি",
  "After your password, confirm it’s you with Face ID, Touch ID, your fingerprint or your device PIN instead of typing a code. Keep your authenticator app too — its backup codes are how you get back in if you lose every device with a passkey.": "পাসওয়ার্ডের পর, কোড টাইপ না করে Face ID, Touch ID, আঙুলের ছাপ বা ডিভাইসের পিন দিয়ে নিশ্চিত করুন যে এটি আপনি। আপনার অথেনটিকেটর অ্যাপও রেখে দিন — পাসকিসহ সব ডিভাইস হারালে এর ব্যাকআপ কোড দিয়েই আবার ঢুকবেন।",
