  "If you lose this device, sign in with one of these instead of your passkey. Each works once, and this is the only time they're shown.": "এই ডিভাইস হারালে পাসকির বদলে এগুলোর একটি দিয়ে সাইন ইন করুন। প্রতিটি একবার কাজ করে, আর এগুলো শুধু এই একবারই দেখানো হচ্ছে।",
