  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "শুধু আপনার স্কুলের সাইন-ইন পাতা বদলায়। মূল সাইটে VolunTrack-এর নাম ও লোগোই থাকে।",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "ব্র্যান্ডিং শুধু আপনার নিজস্ব হোস্টনেমে দেখায়। আপনার এখনও কোনো চালু ডোমেইন নেই — আগে নিজস্ব ডোমেইন-এ একটি সেট আপ করুন, তারপর এখানে যা সংরক্ষণ করবেন তা এর সাইন-ইন পাতায় দেখাবে।",
