  "Each student gets at most one reminder every {n} days.": "প্রত্যেক শিক্ষার্থী প্রতি {n} দিনে সর্বোচ্চ একটি রিমাইন্ডার পায়।",
  "{n} of {total} students still have hours to go": "{total} জনের মধ্যে {n} জন শিক্ষার্থীর এখনও ঘণ্টা বাকি",
