  "reminded {date}": "মনে করানো হয়েছে {date}",
  "Email 1 student how many hours they have left?": "১ জন শিক্ষার্থীকে কত ঘণ্টা বাকি তা ইমেল করবেন?",
  "Email {n} students how many hours they have left?": "{n} জন শিক্ষার্থীকে কত ঘণ্টা বাকি তা ইমেল করবেন?",
  "Say why, so the student can fix it.": "কারণ লিখুন, যাতে শিক্ষার্থী ঠিক করতে পারে।",
  "Entries no supervisor or event organizer has confirmed. They count for now; approve them, or send one back with a reason and it stops counting until the student fixes it.": "যে এন্ট্রিগুলো কোনো সুপারভাইজার বা ইভেন্ট আয়োজক নিশ্চিত করেননি। আপাতত এগুলো গণনা হয়; অনুমোদন করুন, বা কারণসহ একটি ফেরত পাঠান, তাহলে শিক্ষার্থী ঠিক না করা পর্যন্ত সেটি গণনা হবে না।",
  "All ({n})": "সব ({n})",
