  "proof attached": "প্রমাণ সংযুক্ত",
  "What should the student fix? They see this.": "শিক্ষার্থীকে কী ঠিক করতে হবে? সে এটি দেখবে।",
  "Send back": "ফেরত পাঠান",
  "Showing the first 200. Approve or send back some to see more.": "প্রথম ২০০টি দেখানো হচ্ছে। আরও দেখতে কিছু অনুমোদন করুন বা ফেরত পাঠান।",
  "Build report": "রিপোর্ট তৈরি করুন",
  "No students found for this range.": "এই পরিসরে কোনো শিক্ষার্থী পাওয়া যায়নি।",
