  "Summary CSV": "সারাংশ CSV",
  "Summary PDF": "সারাংশ PDF",
  "This range hit the {n}-row limit, so the export is incomplete. Narrow the dates and run it again.": "এই পরিসর {n} সারির সীমায় পৌঁছেছে, তাই এক্সপোর্ট অসম্পূর্ণ। তারিখ কমিয়ে আবার চালান।",
  "Showing 25 of {n}. The exports contain every student.": "{n}টির মধ্যে ২৫টি দেখানো হচ্ছে। এক্সপোর্টে প্রত্যেক শিক্ষার্থী আছে।",
  "Loading domains…": "ডোমেইন লোড হচ্ছে…",
  "Custom domains can be claimed and their ownership verified, but this server cannot issue certificates yet, so a domain cannot go live. Contact VolunTrack support.": "নিজস্ব ডোমেইন দাবি করা ও মালিকানা যাচাই করা যায়, কিন্তু এই সার্ভার এখনও সার্টিফিকেট দিতে পারে না, তাই ডোমেইন চালু করা যায় না। VolunTrack সহায়তার সাথে যোগাযোগ করুন।",
  "Ownership verified": "মালিকানা যাচাই হয়েছে",
  "Ownership not verified yet": "মালিকানা এখনও যাচাই হয়নি",
  "Add these two records at your DNS provider. The TXT record proves you own the domain; the CNAME sends visitors to VolunTrack.": "আপনার DNS প্রোভাইডারে এই দুটি রেকর্ড যোগ করুন। TXT রেকর্ড প্রমাণ করে ডোমেইনটি আপনার; CNAME ভিজিটরদের VolunTrack-এ পাঠায়।",
  "TXT name": "TXT নাম",
  "TXT value": "TXT মান",
