  "Your defaults apply to every school. Add a template, such as “Middle schools”, for schools that need different rules, then assign those schools to it below.": "আপনার ডিফল্ট প্রতিটি স্কুলে প্রযোজ্য। ভিন্ন নিয়ম লাগে এমন স্কুলের জন্য “মাধ্যমিক স্কুল”-এর মতো একটি টেমপ্লেট যোগ করুন, তারপর নিচে সেই স্কুলগুলোকে এতে দিন।",
