  "No requirement": "কোনো প্রয়োজনীয়তা নেই",
  "Hours since {date}. Active means logged hours in the last 30 days.": "{date} থেকে ঘণ্টা। সক্রিয় মানে গত ৩০ দিনে ঘণ্টা লিখেছে।",
  "End this challenge now? Students will stop seeing it.": "এখনই এই চ্যালেঞ্জ শেষ করবেন? শিক্ষার্থীরা আর এটি দেখবে না।",
  "Start a group challenge": "একটি দলগত চ্যালেঞ্জ শুরু করুন",
  "A shared goal for all your students, like “500 hours together by Dec 1”. Everyone sees one progress bar fill up as anyone logs hours.": "আপনার সব শিক্ষার্থীর জন্য একটি যৌথ লক্ষ্য, যেমন “১ ডিসেম্বরের মধ্যে একসাথে ৫০০ ঘণ্টা”। যে কেউ ঘণ্টা লিখলে সবাই একটি অগ্রগতির বার ভরতে দেখে।",
