  "Send this report back": "এই রিপোর্ট ফেরত পাঠান",
  "Why are you sending it back?": "কেন ফেরত পাঠাচ্ছেন?",
  "The student sees this, so say what to fix.": "শিক্ষার্থী এটি দেখবে, তাই কী ঠিক করতে হবে বলুন।",
  "Only your school’s advisers can see these notes.": "শুধু আপনার স্কুলের উপদেষ্টারা এই নোটগুলো দেখতে পারেন।",
  "e.g. Talked to mom about missing hours": "যেমন: বাদ পড়া ঘণ্টা নিয়ে মায়ের সাথে কথা হয়েছে",
  "Add note": "নোট যোগ করুন",
  "No notes yet.": "এখনও কোনো নোট নেই।",
  "Delete note": "নোট মুছুন",
  "This document is kept in your school's own storage.": "এই ডকুমেন্ট আপনার স্কুলের নিজস্ব স্টোরেজে রাখা আছে।",
  "Open document": "ডকুমেন্ট খুলুন",
