  "Reference": "রেফারেন্স",
  "Email it every month": "প্রতি মাসে ইমেল করুন",
  "On the 1st, each person here gets last month’s numbers and the school year so far, with a link to the full report. Up to 5 people; each can unsubscribe.": "১ তারিখে এখানের প্রত্যেকে গত মাসের সংখ্যা আর এই শিক্ষাবর্ষের এ পর্যন্ত হিসাব পান, পুরো রিপোর্টের লিংকসহ। সর্বোচ্চ ৫ জন; প্রত্যেকে আনসাবস্ক্রাইব করতে পারেন।",
  "To change it, go to": "বদলাতে এখানে যান:",
  "See everyone linked to your school, and invite students by email.": "আপনার স্কুলের সাথে যুক্ত সবাইকে দেখুন, এবং ইমেলে শিক্ষার্থীদের আমন্ত্রণ জানান।",
  "Review the PDF proof documents students upload and approve or reject each one — and export every student's hours for a date range.": "শিক্ষার্থীদের আপলোড করা PDF প্রমাণপত্র পর্যালোচনা করে প্রতিটি অনুমোদন বা বাতিল করুন — আর একটি তারিখের পরিসরে প্রত্যেক শিক্ষার্থীর ঘণ্টা এক্সপোর্ট করুন।",
  "Send a message to every student linked to your school at once.": "আপনার স্কুলের সাথে যুক্ত প্রত্যেক শিক্ষার্থীকে একসাথে একটি বার্তা পাঠান।",
  "Add co-admins, let students sign in with your school's Google or Microsoft account, and serve VolunTrack on your own domain.": "সহ-অ্যাডমিন যোগ করুন, শিক্ষার্থীদের আপনার স্কুলের Google বা Microsoft অ্যাকাউন্ট দিয়ে সাইন ইন করতে দিন, আর নিজের ডোমেইনে VolunTrack চালান।",
  "Hour-entry rules": "ঘণ্টা লেখার নিয়ম",
  "Extra questions": "অতিরিক্ত প্রশ্ন",
  "Service-hour requirement": "সেবা-ঘণ্টার প্রয়োজনীয়তা",
  "What an entry must contain before your students can save it.": "শিক্ষার্থীরা সংরক্ষণ করার আগে একটি এন্ট্রিতে যা থাকতে হবে।",
  "Your own questions, added to the bottom of the Log Hours form.": "আপনার নিজের প্রশ্ন, ঘণ্টা লিখুন ফর্মের নিচে যোগ করা হয়।",
  "The total each student is working toward. Shown on their dashboard.": "প্রত্যেক শিক্ষার্থী যে মোটের দিকে কাজ করছে। তাদের ড্যাশবোর্ডে দেখায়।",
  "How students linked to you are allowed to get into their account.": "আপনার সাথে যুক্ত শিক্ষার্থীরা কীভাবে তাদের অ্যাকাউন্টে ঢুকতে পারবে।",
  "Whether each entry has to be signed, and by whom — or carry your own form.": "প্রতিটি এন্ট্রিতে স্বাক্ষর লাগবে কিনা, আর কার — বা আপনার নিজের ফর্ম লাগবে কিনা।",
  "Levels like Bronze, Silver and Gold that students reach as their hours grow. Shown on their dashboard and printed on certificates.": "ব্রোঞ্জ, সিলভার ও গোল্ডের মতো স্তর যা শিক্ষার্থীরা ঘণ্টা বাড়ার সাথে সাথে অর্জন করে। তাদের ড্যাশবোর্ডে দেখায় এবং সার্টিফিকেটে ছাপা হয়।",
