  "On. Every Monday we email you what needs your review, who is behind on hours and what students logged that week.": "চালু। প্রতি সোমবার আমরা আপনাকে ইমেল করে জানাই কী পর্যালোচনা করতে হবে, কে ঘণ্টায় পিছিয়ে আছে আর শিক্ষার্থীরা সেই সপ্তাহে কী লিখেছে।",
  "Off. We won't email you a weekly summary.": "বন্ধ। আমরা আপনাকে সাপ্তাহিক সারাংশ ইমেল করব না।",
