  "The organizer of an event {name} signed up for sees this on their check-in list, only around the day of the event. It isn’t shown anywhere else.": "{name} যে ইভেন্টে সাইন আপ করেছে তার আয়োজক এটি তাঁর চেক-ইন তালিকায় দেখেন, শুধু ইভেন্টের দিনের আশেপাশে। এটি আর কোথাও দেখানো হয় না।",
