  "Your card is full! Keep helping if you want to.": "তোমার কার্ড ভরে গেছে! চাইলে সাহায্য চালিয়ে যাও।",
  "{n} more hours to fill your card.": "কার্ড ভরতে আরও {n} ঘণ্টা।",
  "Kids your age have a small goal. Every little bit helps!": "তোমার বয়সী বাচ্চাদের একটি ছোট লক্ষ্য থাকে। প্রতিটি ছোট সাহায্যও কাজে লাগে!",
  "New main admin": "নতুন প্রধান অ্যাডমিন",
  "A parent must come with volunteers in 5th grade or younger": "৫ম শ্রেণি বা তার নিচের স্বেচ্ছাসেবকদের সাথে একজন অভিভাবককে আসতে হবে",
  "K–5th grade: parent comes too": "K–৫ম শ্রেণি: অভিভাবকও আসবেন",
  "They’ll tell you which parent or guardian is coming when they sign up.": "সাইন আপের সময় তারা জানাবে কোন বাবা-মা বা অভিভাবক আসছেন।",
  "1 entry is saved on this device and waiting to send.": "১টি এন্ট্রি এই ডিভাইসে সংরক্ষিত এবং পাঠানোর অপেক্ষায়।",
  "{n} entries are saved on this device and waiting to send.": "{n}টি এন্ট্রি এই ডিভাইসে সংরক্ষিত এবং পাঠানোর অপেক্ষায়।",
  "Couldn’t reach VolunTrack yet. It keeps trying by itself.": "এখনও VolunTrack-এ পৌঁছানো যায়নি। এটি নিজে থেকেই চেষ্টা চালিয়ে যাচ্ছে।",
  "They send by themselves when you’re back online.": "আবার অনলাইনে এলে এগুলো নিজে থেকেই চলে যাবে।",
  "Send now": "এখনই পাঠান",
  "Saved on this device. It sends by itself when you’re back online.": "এই ডিভাইসে সংরক্ষিত। আবার অনলাইনে এলে এটি নিজে থেকেই চলে যাবে।",
  "Waiting to send": "পাঠানোর অপেক্ষায়",
  "Could not make the packet.": "প্যাকেট তৈরি করা যায়নি।",
  "End-of-year packet": "বছর শেষের প্যাকেট",
  "One ZIP with a folder for each school: summary, every entry, and each student’s hours report.": "প্রতিটি স্কুলের জন্য একটি ফোল্ডারসহ একটি ZIP: সারাংশ, প্রতিটি এন্ট্রি, আর প্রত্যেক শিক্ষার্থীর ঘণ্টার রিপোর্ট।",
  "One ZIP with the summary, every entry, the approval history, certificates for students who met the requirement, and each student’s hours report.": "সারাংশ, প্রতিটি এন্ট্রি, অনুমোদনের ইতিহাস, প্রয়োজনীয়তা পূরণ করা শিক্ষার্থীদের সার্টিফিকেট আর প্রত্যেক শিক্ষার্থীর ঘণ্টার রিপোর্টসহ একটি ZIP।",
  "School year": "শিক্ষাবর্ষ",
  "Making student reports… {done} of {total}": "শিক্ষার্থীদের রিপোর্ট তৈরি হচ্ছে… {total}টির মধ্যে {done}টি",
  "Making the packet…": "প্যাকেট তৈরি হচ্ছে…",
  "Download packet": "প্যাকেট ডাউনলোড করুন",
  "School year runs August 1 to July 31. The ZIP has students’ personal information, so keep it somewhere safe.": "শিক্ষাবর্ষ ১ আগস্ট থেকে ৩১ জুলাই। ZIP-এ শিক্ষার্থীদের ব্যক্তিগত তথ্য আছে, তাই নিরাপদ কোথাও রাখুন।",
  "A parent or guardian must come with you to this event. Who is coming? (their name)": "এই ইভেন্টে আপনার সাথে একজন বাবা-মা বা অভিভাবককে আসতে হবে। কে আসছেন? (তাঁর নাম)",
  "Parent coming: {name}": "যে অভিভাবক আসছেন: {name}",
