  "Tick the times that work for you. \"When I'm free\" then shows only events that start then. Only you see this.": "যে সময়গুলো আপনার সুবিধা টিক দিন। তখন \"যখন আমি ফাঁকা\" শুধু সেই সময়ে শুরু হওয়া ইভেন্ট দেখাবে। এটি শুধু আপনি দেখেন।",
  "Morning is before noon, afternoon noon to 5 PM, evening after 5 PM.": "সকাল মানে দুপুর ১২টার আগে, বিকেল দুপুর ১২টা থেকে বিকেল ৫টা, সন্ধ্যা বিকেল ৫টার পরে।",
  "Could not save when you are free.": "আপনি কখন ফাঁকা তা সংরক্ষণ করা যায়নি।",
