  "{n} entries waiting. Works for {days} days; a new link replaces this one.": "{n}টি এন্ট্রি অপেক্ষায়। {days} দিন কাজ করবে; নতুন লিংক এটিকে বদলে দেয়।",
  "Sign-off link": "অনুমোদনের লিংক",
  "Confirmed by a parent: {name}": "অভিভাবক নিশ্চিত করেছেন: {name}",
  "Could not check you out.": "আপনাকে চেক আউট করানো যায়নি।",
  "You stayed {stayed} of the {minimum} minutes this event asks for, so the organizer will review your hours.": "এই ইভেন্ট {minimum} মিনিট চায়, আপনি থেকেছেন {stayed} মিনিট, তাই আয়োজক আপনার ঘণ্টা পর্যালোচনা করবেন।",
  "1 hour sent to the organizer to sign.": "১ ঘণ্টা আয়োজকের কাছে স্বাক্ষরের জন্য পাঠানো হয়েছে।",
  "{n} hours sent to the organizer to sign.": "{n} ঘণ্টা আয়োজকের কাছে স্বাক্ষরের জন্য পাঠানো হয়েছে।",
  "Checked out.": "চেক আউট হয়েছে।",
  "Leaving? Check out": "চলে যাচ্ছেন? চেক আউট করুন",
  "Checked in at {time}. Type the check-out PIN the organizer gives you.": "{time}-এ চেক ইন হয়েছে। আয়োজক যে চেক-আউট পিন দেন তা লিখুন।",
  "Check-out PIN": "চেক-আউট পিন",
  "Checking out…": "চেক আউট হচ্ছে…",
  "Check out": "চেক আউট করুন",
  "Only their clubs": "শুধু তাঁদের ক্লাব",
  "They see only students in the clubs they advise: student list, hours to check, progress and reports.": "তাঁরা শুধু যে ক্লাবের উপদেষ্টা সেই ক্লাবের শিক্ষার্থীদের দেখেন: শিক্ষার্থী তালিকা, যাচাই করার ঘণ্টা, অগ্রগতি আর রিপোর্ট।",
  "Assignments": "অ্যাসাইনমেন্ট",
