  "No assignments yet.": "এখনও কোনো অ্যাসাইনমেন্ট নেই।",
  "Remove \"{title}\"? Students keep their entries.": "\"{title}\" সরাবেন? শিক্ষার্থীদের এন্ট্রি থেকে যাবে।",
