  "1 student is behind and hasn't logged anything in {n} days.": "১ জন শিক্ষার্থী পিছিয়ে আছে এবং {n} দিন কিছু লেখেনি।",
  "{count} students are behind and haven't logged anything in {n} days.": "{count} জন শিক্ষার্থী পিছিয়ে আছে এবং {n} দিন কিছু লেখেনি।",
